(()=>{
const tree=document.querySelector('.nav-tree'),otherNames=['Configurações'],other=tree?.querySelector('details[data-menu-name="Configurações"]');if(!tree||!other)return;
const members=[...tree.children],others=members.filter(n=>otherNames.includes(n.dataset.menuName)),management=members.filter(n=>!others.includes(n));
const key='cicluz-sidebar-sections-v1';let state={};try{state=JSON.parse(localStorage.getItem(key)||'{}')}catch(e){}
const calendar='<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 11h18M7 15h3M14 15h3"/></svg>';
const agenda=document.createElement('details');agenda.className='agenda-menu-item';agenda.dataset.menuName='Agenda/Atividades';agenda.innerHTML='<summary title="Agenda · Atividades"><span class="drag-handle" aria-label="Segure e arraste para mover Agenda" title="Segure e arraste para mover">⠿</span><span class="menu-icon-circle" style="color:#7c3aed">'+calendar+'</span><span class="menu-name"><span>Agenda</span><small>Atividades</small></span></summary><div class="children"></div>';other.before(agenda);agenda.querySelector('summary').addEventListener('click',e=>{const side=document.querySelector('.side');if(side?.classList.contains('collapsed')){e.preventDefault();document.getElementById('toggleMenu').click();agenda.open=true}});
for(const [label,lista] of [['Lançamentos','lista-diretor-operacoes']]){const button=document.createElement('button');button.type='button';button.textContent=label;button.onclick=()=>{document.querySelectorAll('.nav button').forEach(n=>n.classList.remove('active'));button.classList.add('active');window.CicluzAgenda.abrir(lista)};agenda.querySelector('.children').append(button)}
{const pedidos=document.createElement('button');pedidos.type='button';pedidos.innerHTML='<span class="icone-revisar" aria-hidden="true">'+revisarIcone+'</span>MER - Agenda de Pedidos (revisar)';pedidos.onclick=()=>{document.querySelectorAll('.nav button').forEach(n=>n.classList.remove('active'));pedidos.classList.add('active');document.querySelectorAll('.view').forEach(v=>v.classList.remove('show'));CicluzCompras.abrir('agendamento')};agenda.querySelector('.children').append(pedidos)}
tree.classList.add('sidebar-sectioned');
function section(id,label,nodes,before){const b=document.createElement('button');b.type='button';b.className='sidebar-section-toggle';b.dataset.section=id;b.innerHTML='<span>'+label+'</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 9 7 7 7-7"/></svg>';before.before(b);function update(){const open=state[id]!==false;b.setAttribute('aria-expanded',String(open));b.setAttribute('aria-label',(open?'Recolher ':'Expandir ')+label);nodes.forEach(n=>n.classList.toggle('sidebar-section-hidden',!open))}b.onclick=()=>{state[id]=state[id]===false;update();try{localStorage.setItem(key,JSON.stringify(state))}catch(e){}};update()}
section('management','GESTÃO',management,tree.firstElementChild);section('agenda','AGENDA',[agenda],agenda);section('others','CONFIGURAÇÕES',others,other);
})();
